const screens=[
 '<p class="screen-label">HELLO, WORLD!</p><p class="screen-rkg pixel">RKG</p><p class="screen-copy">Turning curiosity into code.<br>One project at a time.</p>',
 '<p class="screen-extra"><span class="pixel">PLAYER STATS</span>CLASS: DEVELOPER<br>FOCUS: AI + IOT<br>MODE: ALWAYS LEARNING</p>',
 '<p class="screen-extra"><span class="pixel">CURRENT QUEST</span>Build intelligent systems.<br>Connect ideas with code.<br>Keep leveling up.</p>'
];let screenIndex=0;function setScreen(step){screenIndex=(screenIndex+step+screens.length)%screens.length;document.getElementById('console-content').innerHTML=screens[screenIndex];document.querySelector('.screen-bottom span').textContent=`0${screenIndex+1} / 03`;}
document.getElementById('previous').addEventListener('click',()=>setScreen(-1));document.getElementById('next').addEventListener('click',()=>setScreen(1));
const missions={rag:{number:'MISSION 01 / AI + RAG',title:'PRORAG',description:'An advanced retrieval-augmented generation project for asking questions about uploaded documents and tracing answers back to relevant passages.',features:['Document loading, chunking, and semantic embeddings.','FAISS similarity search to retrieve relevant context.','LLM-generated answers with supporting source passages.','FastAPI backend connected to a React interface.'],stack:'FastAPI · React · Sentence Transformers · FAISS · LLMs'},city:{number:'MISSION 02 / AI + IOT',title:'SMART CITY AI',description:'An AI command center that brings sensor readings, vehicle detection, and traffic insights into one dashboard.',features:['YOLOv8 vehicle detection from traffic video.','Sensor records and vehicle counts served through REST APIs.','Traffic predictions and Isolation Forest anomaly detection.','React charts, Leaflet zone maps, and periodic data refresh.'],stack:'Python · FastAPI · SQLAlchemy · YOLOv8 · React · Leaflet'},parking:{number:'MISSION 03 / FULL STACK',title:'SMART PARKING',description:'A full-stack parking application for managing parking slots and reservations.',features:['A visual floor and slot layout with availability status.','Create reservations and view booking history.','Timed bookings with duration extensions.','Release parking slots through backend APIs.'],stack:'Java · Spring Boot · MySQL · JavaScript'}};
const dialog=document.getElementById('mission-dialog');document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const m=missions[button.dataset.project];document.getElementById('mission-number').textContent=m.number;document.getElementById('mission-title').textContent=m.title;document.getElementById('mission-description').textContent=m.description;document.getElementById('mission-features').replaceChildren(...m.features.map(f=>{const li=document.createElement('li');li.textContent=f;return li;}));document.getElementById('mission-stack').textContent=m.stack;dialog.showModal();}));document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
